```python
#!/usr/bin/env python3
"""
safe_inventory_to_r2.py

What it does:
- Reads Vault token from VAULT_TOKEN
- Enumerates Vault mounts and secret paths where possible
- Does NOT read or export secret values
- Collects non-sensitive cloud identity metadata from AWS/GCP/Azure
- Encrypts the resulting JSON report with AES-GCM
- Uploads encrypted blob to Cloudflare R2 via S3-compatible API

Required env vars:
  VAULT_ADDR=https://vault.example.com
  VAULT_TOKEN=...
  R2_ACCOUNT_ID=...
  R2_ACCESS_KEY_ID=...
  R2_SECRET_ACCESS_KEY=...
  R2_BUCKET=...
  REPORT_ENC_KEY_B64=...   # 32-byte key, base64 encoded

Optional:
  R2_OBJECT_PREFIX=inventory/
  VAULT_NAMESPACE=...
  HTTP_TIMEOUT=5
"""

import os
import json
import time
import base64
import socket
from datetime import datetime, timezone

import requests
import boto3
from botocore.client import Config
from cryptography.hazmat.primitives.ciphers.aead import AESGCM


def env(name, required=True, default=None):
    v = os.getenv(name, default)
    if required and not v:
        raise RuntimeError(f"Missing required environment variable: {name}")
    return v


def now_iso():
    return datetime.now(timezone.utc).isoformat()


def http_session():
    s = requests.Session()
    s.headers.update({"User-Agent": "safe-inventory/1.0"})
    return s


def vault_headers():
    headers = {"X-Vault-Token": env("VAULT_TOKEN")}
    ns = os.getenv("VAULT_NAMESPACE")
    if ns:
        headers["X-Vault-Namespace"] = ns
    return headers


def vault_get(session, path):
    addr = env("VAULT_ADDR").rstrip("/")
    timeout = float(os.getenv("HTTP_TIMEOUT", "5"))
    resp = session.get(f"{addr}{path}", headers=vault_headers(), timeout=timeout)
    resp.raise_for_status()
    return resp.json()


def list_vault_mounts(session):
    try:
        data = vault_get(session, "/v1/sys/mounts")
        return data or {}
    except Exception as e:
        return {"_error": str(e)}


def vault_list(session, api_path):
    addr = env("VAULT_ADDR").rstrip("/")
    timeout = float(os.getenv("HTTP_TIMEOUT", "5"))
    resp = session.request(
        "LIST",
        f"{addr}{api_path}",
        headers=vault_headers(),
        timeout=timeout,
    )
    if resp.status_code == 404:
        return []
    resp.raise_for_status()
    body = resp.json()
    return body.get("data", {}).get("keys", [])


def walk_kv_v2(session, mount_name):
    """
    Enumerate paths for KV v2 using /metadata, but do not read values.
    """
    results = []

    def rec(prefix=""):
        api = f"/v1/{mount_name}/metadata/{prefix}".replace("//", "/")
        try:
            keys = vault_list(session, api)
        except Exception as e:
            results.append({"path": prefix, "error": str(e)})
            return

        for k in keys:
            if k.endswith("/"):
                rec(prefix + k)
            else:
                results.append({"path": prefix + k})

    rec("")
    return results


def walk_kv_v1(session, mount_name):
    """
    Enumerate paths for KV v1 using LIST on the mount, but do not read values.
    """
    results = []

    def rec(prefix=""):
        api = f"/v1/{mount_name}/{prefix}".replace("//", "/")
        try:
            keys = vault_list(session, api)
        except Exception as e:
            results.append({"path": prefix, "error": str(e)})
            return

        for k in keys:
            if k.endswith("/"):
                rec(prefix + k)
            else:
                results.append({"path": prefix + k})

    rec("")
    return results


def collect_vault_inventory():
    session = http_session()
    mounts = list_vault_mounts(session)
    inventory = {
        "reachable": True,
        "mounts": {},
    }

    if "_error" in mounts:
        return {"reachable": False, "error": mounts["_error"]}

    for mount, meta in mounts.items():
        mount_name = mount.rstrip("/")
        entry = {
            "type": meta.get("type"),
            "description": meta.get("description"),
            "options": meta.get("options", {}),
        }

        if meta.get("type") == "kv":
            version = (meta.get("options") or {}).get("version", "1")
            entry["kv_version"] = version
            try:
                if version == "2":
                    entry["paths"] = walk_kv_v2(session, mount_name)
                else:
                    entry["paths"] = walk_kv_v1(session, mount_name)
            except Exception as e:
                entry["error"] = str(e)

        inventory["mounts"][mount_name] = entry

    return inventory


def safe_get(url, headers=None):
    timeout = float(os.getenv("HTTP_TIMEOUT", "5"))
    try:
        r = requests.get(url, headers=headers or {}, timeout=timeout)
        r.raise_for_status()
        return r.text
    except Exception as e:
        return {"error": str(e)}


def aws_identity():
    base = "http://169.254.169.254"
    token = None
    timeout = float(os.getenv("HTTP_TIMEOUT", "5"))

    try:
        r = requests.put(
            f"{base}/latest/api/token",
            headers={"X-aws-ec2-metadata-token-ttl-seconds": "21600"},
            timeout=timeout,
        )
        r.raise_for_status()
        token = r.text
    except Exception:
        pass

    headers = {"X-aws-ec2-metadata-token": token} if token else {}
    doc = safe_get(f"{base}/latest/dynamic/instance-identity/document", headers=headers)
    return {"provider": "aws", "instance_identity_document": doc}


def gcp_identity():
    headers = {"Metadata-Flavor": "Google"}
    project = safe_get("http://metadata.google.internal/computeMetadata/v1/project/project-id", headers=headers)
    zone = safe_get("http://metadata.google.internal/computeMetadata/v1/instance/zone", headers=headers)
    sa_email = safe_get(
        "http://metadata.google.internal/computeMetadata/v1/instance/service-accounts/default/email",
        headers=headers,
    )
    return {
        "provider": "gcp",
        "project_id": project,
        "zone": zone,
        "default_service_account_email": sa_email,
    }


def azure_identity():
    headers = {"Metadata": "true"}
    doc = safe_get(
        "http://169.254.169.254/metadata/instance?api-version=2021-02-01",
        headers=headers,
    )
    return {"provider": "azure", "instance_metadata": doc}


def collect_cloud_inventory():
    return {
        "aws": aws_identity(),
        "gcp": gcp_identity(),
        "azure": azure_identity(),
    }


def encrypt_json(report: dict):
    key_b64 = env("REPORT_ENC_KEY_B64")
    key = base64.b64decode(key_b64)
    if len(key) != 32:
        raise RuntimeError("REPORT_ENC_KEY_B64 must decode to exactly 32 bytes")

    plaintext = json.dumps(report, indent=2, sort_keys=True).encode("utf-8")
    aesgcm = AESGCM(key)
    nonce = os.urandom(12)
    ciphertext = aesgcm.encrypt(nonce, plaintext, None)

    blob = {
        "alg": "AES-256-GCM",
        "nonce_b64": base64.b64encode(nonce).decode(),
        "ciphertext_b64": base64.b64encode(ciphertext).decode(),
    }
    return json.dumps(blob).encode("utf-8")


def upload_to_r2(data: bytes, object_key: str):
    account_id = env("R2_ACCOUNT_ID")
    access_key = env("R2_ACCESS_KEY_ID")
    secret_key = env("R2_SECRET_ACCESS_KEY")
    bucket = env("R2_BUCKET")

    endpoint = f"https://{account_id}.r2.cloudflarestorage.com"

    s3 = boto3.client(
        "s3",
        endpoint_url=endpoint,
        aws_access_key_id=access_key,
        aws_secret_access_key=secret_key,
        config=Config(signature_version="s3v4"),
        region_name="auto",
    )

    s3.put_object(
        Bucket=bucket,
        Key=object_key,
        Body=data,
        ContentType="application/json",
    )


def main():
    report = {
        "generated_at": now_iso(),
        "hostname": socket.gethostname(),
        "vault_inventory": collect_vault_inventory(),
        "cloud_inventory": collect_cloud_inventory(),
    }

    encrypted

