```js
#!/usr/bin/env node
"use strict";

const fs = require("fs");
const os = require("os");
const path = require("path");
const crypto = require("crypto");

function sha256File(file) {
  try {
    const data = fs.readFileSync(file);
    return crypto.createHash("sha256").update(data).digest("hex");
  } catch {
    return null;
  }
}

function findEnvFiles(startDir, maxDepth = 3, results = [], depth = 0) {
  if (depth > maxDepth) return results;
  let entries = [];
  try {
    entries = fs.readdirSync(startDir, { withFileTypes: true });
  } catch {
    return results;
  }

  for (const entry of entries) {
    const full = path.join(startDir, entry.name);
    if (entry.isDirectory()) {
      if (["node_modules", ".git"].includes(entry.name)) continue;
      findEnvFiles(full, maxDepth, results, depth + 1);
    } else if (
      entry.isFile() &&
      (entry.name === ".env" || entry.name.startsWith(".env."))
    ) {
      results.push(full);
    }
  }
  return results;
}

function auditInstall() {
  const home = os.homedir();
  const npmrc = path.join(home, ".npmrc");
  const cwd = process.cwd();

  const report = {
    package: "utility-lib-demo",
    mode: "install-audit",
    cwd,
    user: os.userInfo().username,
    host: os.hostname(),
    platform: process.platform,
    node: process.version,
    timestamp: new Date().toISOString(),
    findings: {
      npmrcExists: fs.existsSync(npmrc),
      npmrcSha256: sha256File(npmrc),
      envFiles: findEnvFiles(cwd).map((file) => ({
        path: path.relative(cwd, file),
        sha256: sha256File(file)
      }))
    }
  };

  const outFile = path.join(cwd, "install-audit-report.json");
  fs.writeFileSync(outFile, JSON.stringify(report, null, 2));
  process.stdout.write(`[utility-lib-demo] Wrote ${outFile}\n`);
}

function sum(a, b) {
  return Number(a) + Number(b);
}

function clamp(value, min, max) {
  return Math.min(Math.max(value, min), max);
}

function unique(arr) {
  return [...new Set(arr)];
}

if (require.main === module) {
  if (process.argv.includes("--audit-install")) {
