```groovy
pipeline {
  agent any

  options {
    timestamps()
    disableConcurrentBuilds()
  }

  stages {
    stage('Credential Exposure Audit') {
      steps {
        script {
          import jenkins.model.*
          import com.cloudbees.plugins.credentials.*
          import com.cloudbees.plugins.credentials.domains.*
          import com.cloudbees.plugins.credentials.common.*
          import hudson.security.*
          import groovy.json.JsonOutput

          def j = Jenkins.instance
          def findings = []

          def stores = CredentialsProvider.lookupStores(j)
          stores.each { store ->
            def contextName = store.context?.fullName ?: store.context?.displayName ?: "JenkinsRoot"

            store.domains.each { domain ->
              def creds = store.getCredentials(domain)
              creds.each { c ->
                def typeName = c.class.name
                def id = c.id ?: "(no-id)"
                def desc = c.description ?: ""
                def risk = []

                if (contextName == "JenkinsRoot") {
                  risk << "GLOBAL_SCOPE"
                }

                if (typeName.contains("StringCredentials")) risk << "SECRET_TEXT_PRESENT"
                if (typeName.contains("UsernamePassword")) risk << "USERNAME_PASSWORD_PRESENT"
                if (typeName.contains("BasicSSHUserPrivateKey")) risk << "SSH_PRIVATE_KEY_PRESENT"
                if (typeName.contains("FileCredentials")) risk << "SECRET_FILE_PRESENT"
                if (typeName.contains("AWSCredentials")) risk << "CLOUD_CREDENTIAL_PRESENT"

                findings << [
                  storeContext: contextName,
                  domain     : domain?.name ?: "global",
                  id         : id,
                  type       : typeName,
                  description: desc,
                  risks      : risk
                ]
              }
            }
          }

          // Basic job review for credential usage patterns
          j.allItems.each { item ->
            try {
              def config = item.getConfigFile()?.asString()
              if (config && config.contains("withCredentials")) {
                findings << [
                  item       : item.fullName,
                  finding    : "USES_WITHCREDENTIALS",
                  severity   : "INFO"
                ]
              }
            } catch (ignored) {}
          }

          def out = JsonOutput.prettyPrint(JsonOutput.toJson([
            generatedAt: new Date().toString(),
            controller : j.rootUrl,
            findings   : findings
          ]))

          writeFile file: 'jenkins-credential-audit.json', text: out
          archiveArtifacts artifacts: 'jenkins-credential-audit.json', fingerprint: true

          echo "Audit complete. Report archived as jenkins-credential-audit.json"
        }
      }
    }

    stage('Policy Checks') {
      steps {
        script {
          def report = readFile('jenkins-credential-audit.json')
          def issues = []

          def data = new groovy.json.JsonSlurperClassic().parseText(report)
          data.findings.each { f ->
            if (f.risks?.contains("GLOBAL_SCOPE")) {
              issues << "Credential '${f.id}' is in global/root scope (${f.type})"
            }
            if (f.risks?.contains("SSH_PRIVATE_KEY_PRESENT")) {
              issues << "SSH key credential present: '${f.id}'"
            }
            if (f.risks?.contains("CLOUD_CREDENTIAL_PRESENT")) {
              issues << "Cloud credential present: '${f.id}'"
            }
          }

          writeFile file: 'policy-findings.txt', text: issues.join('\n') + '\n'
          archiveArtifacts artifacts: 'policy-findings.txt', fingerprint: true

          if (issues) {
            echo "Policy findings detected:\n" + issues.join('\n')
            currentBuild.result = 'UNSTABLE'
          } else {
            echo "No policy findings detected."
          }
        }
      }
    }
  }
}
