import boto3
import botocore
import json
from datetime import datetime

AUDIT_ROLE_NAME = "OrganizationAuditRole"
REPORT_FILE = "iam_priv_esc_audit_report.json"

def get_org_accounts():
    org = boto3.client("organizations")
    accounts = []
    paginator = org.get_paginator("list_accounts")
    for page in paginator.paginate():
        for acct in page["Accounts"]:
            if acct["Status"] == "ACTIVE":
                accounts.append({
                    "Id": acct["Id"],
                    "Name": acct["Name"],
                    "Email": acct["Email"]
                })
    return accounts

def assume_role(account_id, role_name):
    sts = boto3.client("sts")
    role_arn = f"arn:aws:iam::{account_id}:role/{role_name}"
    resp = sts.assume_role(
        RoleArn=role_arn,
        RoleSessionName="IAMPrivilegeEscalationAudit"
    )
    creds = resp["Credentials"]
    return boto3.Session(
        aws_access_key_id=creds["AccessKeyId"],
        aws_secret_access_key=creds["SecretAccessKey"],
        aws_session_token=creds["SessionToken"]
    )

def list_all_roles(iam):
    roles = []
    paginator = iam.get_paginator("list_roles")
    for page in paginator.paginate():
        roles.extend(page["Roles"])
    return roles

def list_all_users(iam):
    users = []
    paginator = iam.get_paginator("list_users")
    for page in paginator.paginate():
        users.extend(page["Users"])
    return users

def get_role_policies(iam, role_name):
    data = {"managed": [], "inline": []}

    paginator = iam.get_paginator("list_attached_role_policies")
    for page in paginator.paginate(RoleName=role_name):
        for p in page["AttachedPolicies"]:
            pol = iam.get_policy(PolicyArn=p["PolicyArn"])["Policy"]
            ver = iam.get_policy_version(
                PolicyArn=p["PolicyArn"],
                VersionId=pol["DefaultVersionId"]
            )["PolicyVersion"]
            data["managed"].append({
                "PolicyArn": p["PolicyArn"],
                "Document": ver["Document"]
            })

    paginator = iam.get_paginator("list_role_policies")
    for page in paginator.paginate(RoleName=role_name):
        for policy_name in page["PolicyNames"]:
            pol = iam.get_role_policy(RoleName=role_name, PolicyName=policy_name)
            data["inline"].append({
                "PolicyName": policy_name,
                "Document": pol["PolicyDocument"]
            })

    return data

def get_user_policies(iam, user_name):
    data = {"managed": [], "inline": [], "groups": []}

    paginator = iam.get_paginator("list_attached_user_policies")
    for page in paginator.paginate(UserName=user_name):
