```groovy
package org.company.cicd

class ConventionalCommitVersioner implements Serializable {
    def steps

    ConventionalCommitVersioner(steps) {
        this.steps = steps
    }

    String bumpVersion(Map config = [:]) {
        String versionFile = config.baseVersionFile ?: 'VERSION'
        String tagPrefix = config.tagPrefix ?: 'v'

        String currentVersion = readCurrentVersion(versionFile)
        List<Integer> parts = currentVersion.tokenize('.').collect { it as Integer }

        String commits = steps.sh(
            script: "git log --pretty=format:%s \$(git describe --tags --abbrev=0 2>/dev/null || echo '')..HEAD || git log --pretty=format:%s -n 50",
            returnStdout: true
        ).trim()

        String level = determineBumpLevel(commits)

        switch (level) {
            case 'major':
                parts[0] = parts[0] + 1
                parts[1] = 0
                parts[2] = 0
                break
            case 'minor':
                parts[1] = parts[1] + 1
                parts[2] = 0
                break
            default:
                parts[2] = parts[2] + 1
        }

        String nextVersion = parts.join('.')
        steps.writeFile(file: versionFile, text: "${nextVersion}\n")

        steps.sh """
            git config user.email "jenkins@local"
            git config user.name "jenkins"
            git add ${versionFile}
            git commit -m "chore(release): ${tagPrefix}${nextVersion}" || true
            git tag ${tagPrefix}${nextVersion} || true
        """

        return nextVersion
    }

    private String readCurrentVersion(String versionFile) {
        if (!steps.fileExists(versionFile)) {
            steps.writeFile(file: versionFile, text: "0.1.0\n")
            return "0.1.0"
        }
        return steps.readFile(versionFile).trim()
    }

    private String determineBumpLevel(String commits) {
        if (!commits?.trim()) {
            return 'patch'
        }

        def lines = commits.readLines()

        boolean major = lines.any { it.contains('BREAKING CHANGE') || it ==~ /.*!:.*/ }
        boolean minor = lines.any { it ==~ /^(feat)(\\(.+\\))?:.*/ }
        boolean patch = lines.any { it ==~ /^(fix|perf|refactor)(\\(.+\\))?:.*/ }

        if (major) return 'major'
        if (minor) return 'minor'
        if (patch) return 'patch'
        return 'patch'
    }
}
