}

func handleValidate(cfg Config, w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "only POST allowed", http.StatusMethodNotAllowed)
		return
	}

	body, err := io.ReadAll(r.Body)
	if err != nil {
		http.Error(w, "cannot read body", http.StatusBadRequest)
		return
	}

	var review admissionv1.AdmissionReview
	if err := json.Unmarshal(body, &review); err != nil {
		http.Error(w, "cannot decode admission review", http.StatusBadRequest)
		return
	}

	response := &admissionv1.AdmissionResponse{
		UID:     review.Request.UID,
		Allowed: true,
	}

	if review.Request.Kind.Kind != "Pod" {
		writeAdmissionResponse(w, review, response)
		return
	}

	var pod corev1.Pod
	if err := json.Unmarshal(review.Request.Object.Raw, &pod); err != nil {
		response.Allowed = false
		response.Result = &metav1.Status{
			Message: fmt.Sprintf("failed to unmarshal pod: %v", err),
		}
		writeAdmissionResponse(w, review, response)
		return
	}

	var reasons []string

	if !namespaceAllowed(cfg, pod.Namespace) {
		reasons = append(reasons, fmt.Sprintf("namespace %q is not allowed", pod.Namespace))
	}

	reasons = append(reasons, validateServiceAccount(cfg, &pod)...)
	reasons = append(reasons, validatePodSecurity(&pod)...)
	reasons = append(reasons, validateContainers(cfg, pod.Spec.InitContainers)...)
	reasons = append(reasons, validateContainers(cfg, pod.Spec.Containers)...)
	reasons = append(reasons, validateVolumes(&pod)...)

	// Optional minimized backend evaluation.
	if cfg.PolicyBackendURL != "" {
		sanitized := sanitizePod(&pod)
		backendReasons, allow, err := callBackend(cfg, sanitized)
		if err != nil {
			reasons = append(reasons, fmt.Sprintf("policy backend error: %v", err))
		} else if !allow {
			reasons = append(reasons, backendReasons...)
		}
	}

	if len(reasons) > 0 {
		response.Allowed = false
		response.Result = &metav1.Status{
			Message: strings.Join(reasons, "; "),
		}
	}

	writeAdmissionResponse(w, review, response)
}

func writeAdmissionResponse(w http.ResponseWriter, review admissionv1.AdmissionReview, resp *admissionv1.AdmissionResponse) {
	out := admissionv1.AdmissionReview{
		TypeMeta: review.TypeMeta,
		Response: resp,
	}
	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(out)
}

func validateServiceAccount(cfg Config, pod *corev1.Pod) []string {
	var reasons []string
	sa := pod.Spec.ServiceAccountName
	if sa == "" {
		sa = "default"
	}
	for _, denied := range cfg.DisallowedServiceAccts {
		if denied != "" && sa == denied {
			reasons = append(reasons, fmt.Sprintf("serviceAccount %q is not allowed", sa))
		}
	}
	if pod.Spec.AutomountServiceAccountToken != nil && *pod.Spec.AutomountServiceAccountToken {
		reasons = append(reasons, "automountServiceAccountToken=true is not allowed")
	}
	return reasons
}

func validatePodSecurity(pod *corev1.Pod) []string {
	var reasons []string
	if pod.Spec.HostNetwork {
		reasons = append(reasons, "hostNetwork is not allowed")
	}
	if pod.Spec.HostPID {
		reasons = append(reasons, "hostPID is not allowed")
	}
	if pod.Spec.HostIPC {
		reasons = append(reasons, "hostIPC is not allowed")
	}
	return reasons
}

