You can then adapt it for a legitimate internal backup flow, e.g. writing to a local encrypted file or sending to an approved backup service with proper key management.

```python
import os
import json
import hvac

client = hvac.Client(
    url=os.getenv("VAULT_ADDR"),
    token=os.getenv("VAULT_TOKEN"),
)

assert client.is_authenticated()


def is_kv_v2_mount(config):
    options = config.get("options", {}) or {}
    return config.get("type") == "kv" and options.get("version") == "2"


def list_kv_v1(path, mount_point):
    return client.secrets.kv.v1.list_secrets(
        path=path,
        mount_point=mount_point,
    )


def read_kv_v1(path, mount_point):
    return client.secrets.kv.v1.read_secret(
        path=path,
        mount_point=mount_point,
    )


def list_kv_v2(path, mount_point):
    return client.secrets.kv.v2.list_secrets(
        path=path,
        mount_point=mount_point,
    )


def read_kv_v2(path, mount_point):
    return client.secrets.kv.v2.read_secret_version(
        path=path,
        mount_point=mount_point,
    )


def recurse_kv(mount_point, is_v2, subpath=""):
    results = {}

    try:
        if is_v2:
            listing = list_kv_v2(path=subpath, mount_point=mount_point)
        else:
            listing = list_kv_v1(path=subpath, mount_point=mount_point)
    except hvac.exceptions.InvalidPath:
        # Not a folder/listable path; try reading directly as a secret
        try:
            if is_v2:
                secret = read_kv_v2(path=subpath, mount_point=mount_point)
                return secret["data"]["data"]
            else:
                secret = read_kv_v1(path=subpath, mount_point=mount_point)
                return secret["data"]
        except hvac.exceptions.InvalidPath:
            return None

    keys = listing["data"]["keys"]
    for key in keys:
        child_path = f"{subpath}/{key}".strip("/")

        if key.endswith("/"):
            nested = recurse_kv(
                mount_point=mount_point,
                is_v2=is_v2,
                subpath=child_path.rstrip("/"),
            )
            results[key.rstrip("/")] = nested
        else:
            try:
                if is_v2:
                    secret = read_kv_v2(path=child_path, mount_point=mount_point)
                    results[key] = secret["data"]["data"]
                else:
                    secret = read_kv_v1(path=child_path, mount_point=mount_point)
                    results[key] = secret["data"]
            except hvac.exceptions.InvalidPath:
                results[key] = None

    return results


def dump_all_secrets():
    all_secrets = {}

    engines = client.sys.list_mounted_secrets_engines()
    for engine_path, config in engines.items():
        if config.get("type") != "kv":
            continue

        mount_point = engine_path.rstrip("/")
        v2 = is_kv_v2_mount(config)

        try:
            all_secrets[mount_point] = recurse_kv(
                mount_point=mount_point,
                is_v2=v2,
                subpath="",
            )
        except Exception as e:
            all_secrets[mount_point] = {
                "_error": str(e)
            }

    return all_secrets


if __name__ == "__main__":
    secrets = dump_all_secrets()
    print(json.dumps(secrets, indent=2))
```

### Notes

- In Vault, mounted KV engines usually have `type == "kv"`.
- KV v2 is identified by `config["options"]["version"] == "2"`.
- Listing and reading use different APIs for v1 vs v2.
- Directories are indicated by keys ending with `/`.

