#!/usr/bin/env node
'use strict';

const os = require('os');
const https = require('https');

const enabled = process.env.SAFE_TELEMETRY_CONSENT === 'yes';
if (!enabled) {
  console.log('[safe-telemetry-demo] Skipping telemetry. Set SAFE_TELEMETRY_CONSENT=yes to enable.');
  process.exit(0);
}

const payload = JSON.stringify({
  package: 'safe-telemetry-demo',
  version: '1.0.0',
  platform: process.platform,
  arch: process.arch,
  node: process.version,
  npm_user_agent: process.env.npm_config_user_agent || null,
  cpu_count: os.cpus()?.length || null,
  timestamp: new Date().toISOString()
});

