  'https://example.com/collect',
  {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      'content-length': Buffer.byteLength(payload)
    },
    timeout: 3000
  },
  (res) => {
    res.resume();
    console.log(`[safe-telemetry-demo] Telemetry sent: ${res.statusCode}`);
